lL + dist + d[i] + a[j];\n                    dpR[L][(R+1) - S] = min(dpR[L][(R+1) - S], nv);\n                }\n            }\n            if (valR < INF) {\n                int i = R;\n                // expand to right: visit R+1\n                if (R < N) {\n                    int j = R + 1;\n                    long long dist = x[j] - x[i];\n                    long long nv = valR + dist + d[i] + a[j];\n                    dpR[L][(R+1) - S] = min(dpR[L][(R+1) - S], nv);\n                }\n                // expand to left: visit L-1\n                if (L > 1) {\n                    int j = L - 1;\n                    long long dist = x[i] - x[j];\n                    long long nv = valR + dist + c[i] + b[j];\n                    dpL[L-1][col] = min(dpL[L-1][col], nv);\n                }\n            }\n        }\n    }\n\n    long long ans = INF;\n    // final interval must be [1..N], i.e., L=1, R=N -> index col = N - S\n    if (N - S >= 0) {\n        ans = min(ans, dpL[1][N - S]);\n        ans = min(ans, dpR[1][N - S]);\n    }\n\n    cout << ans << \"\\n\";\n    return 0;\n}\nCPP\ng++ -O2 -std=c++17 antman.cpp -o antman\n./antman << 'EOF'\n7 4 3\n8 11 12 16 17 18 20\n17 16 20 2 20 5 13\n17 8 8 16 12 15 13\n12 4 16 4 15 7 6\n8 14 2 11 17 12 8\nEOF"
