1, 20)\n        c[i] = random.randint(1, 20)\n        d[i] = random.randint(1, 20)\n    return n, s, e, x, a, b, c, d\n\n\ndef main():\n    trials = 200\n    for t in range(trials):\n        n, s, e, x, a, b, c, d = random_case()\n        dp_ans = run_dp(n, s, e, x, a, b, c, d)\n        brute_ans = brute_case(n, s, e, x, a, b, c, d)\n        if dp_ans != brute_ans:\n            print(\"Mismatch on trial\", t)\n            print(\"Input:\")\n            print(n, s, e)\n            print(\"x:\", x[1:])\n            print(\"a:\", a[1:])\n            print(\"b:\", b[1:])\n            print(\"c:\", c[1:])\n            print(\"d:\", d[1:])\n            print(\"DP:\", dp_ans, \"Brute:\", brute_ans)\n            print(\"Terminating...\")\n            return\n    print(\"All tests passed for\", trials, \"random cases.\")\n\nif __name__ == \"__main__\":\n    main()\nPY'\n" },
