        g[u].push_back(v); g[v].push_back(u);
    }

    // Build parent and postorder using iterative DFS
    vector<int> parent(n+1, -1);
    vector<int> order; order.reserve(n);
    vector<int> st; st.push_back(1); parent[1] = 0;
    while(!st.empty()){
        int v = st.back(); st.pop_back();
        order.push_back(v);
        for(int u : g[v]){
            if(parent[u] == -1){
                parent[u] = v;
                st.push_back(u);
            }
        }
    }

    struct Node { long long a[2][2]; };
    vector<Node> dp(n+1);

    // Process in reverse order (postorder)
    for(int idx = (int)order.size()-1; idx >= 0; --idx){
        int v = order[idx];
        // collect children
        vector<int> child;
        for(int u : g[v]) if(parent[u] == v) child.push_back(u);

        // d = 0
        long long old0 = 1, old1 = 0; // hv = 0/1 counts
        for(int u : child){
            long long A = (dp[u].a[0][0] + dp[u].a[1][0]) % MOD; // edge (v,u) not chosen
            long long B = (dp[u].a[0][1] + dp[u].a[1][1]) % MOD; // edge (v,u) chosen (allowed when not both 1)
            long long new0 = (old0 * A) % MOD;
