        old0 = 1; old1 = 0;
        for(int u : child){
            long long A = (dp[u].a[0][0] + dp[u].a[1][0]) % MOD;
            long long B = dp[u].a[0][1] % MOD; // since d=1, edge (v,u) chosen allowed only when child != 1
            long long new0 = (old0 * A) % MOD;
            long long new1 = ( (old1 * A) % MOD + ((old0 + old1) % MOD) * B % MOD ) % MOD;
            old0 = new0; old1 = new1;
        }
