using namespace std;

struct DSU {
    int n;
    vector<int> p, sz;
    DSU(int n=0){ init(n); }
    void init(int n_) { n = n_; p.resize(n+1); sz.assign(n+1,1); for(int i=1;i<=n;i++) p[i]=i; }
    int find(int x){ return p[x]==x ? x : p[x] = find(p[x]); }
    bool unite(int a, int b){ a = find(a); b = find(b); if(a==b) return false; if(sz[a] < sz[b]) swap(a,b); p[b] = a; sz[a] += sz[b]; return true; }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if(!(cin >> n >> m)) return 0;
    vector<int> U(m+1), V(m+1), W(m+1);
    int maxW = 0;
    for(int i=1; i<=m; ++i){
        int u,v,w; cin >> u >> v >> w; U[i]=u; V[i]=v; W[i]=w; if(w>maxW) maxW = w;
    }

    vector<vector<pair<int,int>>> byWeightQueries(maxW+1);
    vector<vector<int>> edgesByWeight(maxW+1);
    for(int i=1; i<=m; ++i) edgesByWeight[W[i]].push_back(i);

    int q; cin >> q;
    vector<char> ans(q, 1);

    for(int qi=0; qi<q; ++qi){
        int k; cin >> k;
        for(int t=0; t<k; ++t){
            int ei; cin >> ei;
            byWeightQueries[W[ei]].push_back({qi, ei});
        }
    }

    DSU dsu(n);

    for(int w=1; w<=maxW; ++w){
        auto &bucket = byWeightQueries[w];
        if(!bucket.empty()){
            sort(bucket.begin(), bucket.end(), [](const pair<int,int>& a, const pair<int,int>& b){
                if(a.first != b.first) return a.first < b.first;
                return a.second < b.second;
            });

            size_t idx = 0;
            while(idx < bucket.size()){
                int qid = bucket[idx].first;
                vector<pair<int,int>> edgeReps; // endpoints reps
                bool bad = false;
                while(idx < bucket.size() && bucket[idx].first == qid){
                    int e = bucket[idx].second;
