                    if(a == b) bad = true;
                    idx++;
                }
                if(bad){
                    ans[qid] = 0;
                    continue;
                }
                unordered_map<int,int> mp;
                mp.reserve(edgeReps.size()*2+1);
                int cur = 0;
                for(auto &pr : edgeReps){
                    int a = pr.first, b = pr.second;
                    if(mp.find(a) == mp.end()) mp[a] = cur++;
                    if(mp.find(b) == mp.end()) mp[b] = cur++;
                }
                vector<int> lp(cur);
                iota(lp.begin(), lp.end(), 0);
                vector<int> rank(cur,0);
                function<int(int)> lfind = [&](int x){ while(lp[x] != x){ lp[x] = lp[lp[x]]; x = lp[x]; } return x; };
                auto lunion = [&](int a, int b){ a = lfind(a); b = lfind(b); if(a==b) return false; if(rank[a] < rank[b]) swap(a,b); lp[b] = a; if(rank[a] == ra
nk[b]) rank[a]++; return true; };
                for(auto &pr : edgeReps){
                    int ia = mp[pr.first], ib = mp[pr.second];
                    int ra = lfind(ia), rb = lfind(ib);
                    if(ra == rb){ ans[qid] = 0; break; }
                    lunion(ra, rb);
                }
            }
        }
        for(int e : edgesByWeight[w]) dsu.unite(U[e], V[e]);
    }

    for(int i=0; i<q; ++i){ cout << (ans[i] ? "YES" : "NO") << "\n"; }
    return 0;
}

