import random
import subprocess
from itertools import combinations

# Brute force verifier for small graphs

def brute_force(n, edges, queries):
    m = len(edges)
    # edges: list of (u, v, w)
    # Compute true MST weight using Kruskal
    parent = list(range(n+1))
    rank = [0]*(n+1)
    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a
    def unite(a,b):
        a = find(a); b = find(b)
        if a == b: return False
        if rank[a] < rank[b]: a,b = b,a
        parent[b] = a
        if rank[a] == rank[b]: rank[a] += 1
        return True
    order = sorted(range(m), key=lambda i: edges[i][2])
    mst_weight = 0
    cnt = 0
    for i in order:
        u,v,w = edges[i]
        if unite(u,v):
            mst_weight += w
            cnt += 1
            if cnt == n-1: break
    # For each query, brute force: exists a spanning tree containing the query edges with total weight == mst_weight?
    results = []
    for S in queries:
        Sset = set(S)
        # enumerate all subsets of edges of size n-1 that form a tree
        found = False
        for comb in combinations(range(m), n-1):
            if not Sset.issubset(set(comb)): continue
            # check if comb forms a tree
            p = list(range(n+1))
            r = [0]*(n+1)
            def f(x):
                while p[x] != x:
                    p[x] = p[p[x]]
                    x = p[x]
                return x
            def u(a,b):
                a = f(a); b = f(b)
                if a==b: return False
                if r[a] < r[b]: a,b = b,a
                p[b] = a
                if r[a] == r[b]: r[a]+=1
                return True
            ok = True
            tot = 0
            for ei in comb:
                u1,v1,w = edges[ei]
                if not u(u1,v1):
                    ok = False; break
                tot += w
            if ok and tot == mst_weight:
                found = True
                break
        results.append("YES" if found else "NO")
    return results

# Random test generator and verifier
random.seed(0)
for t in range(100):
    n = random.randint(2, 6)
    # ensure connected graph: start with a tree, then add extra edges
    edges = []
    # create tree
    for v in range(2, n+1):
        u = random.randint(1, v-1)
        w = random.randint(1, 5)
        edges.append((u, v, w))
    m = len(edges)
    # add some extra edges
    extra = random.randint(0, max(0, n-2))
    for _ in range(extra):
        u = random.randint(1, n)
        v = random.randint(1, n)
        if u == v: continue
        if u > v: u,v = v,u
        w = random.randint(1, 5)
        edges.append((u,v,w))
    m = len(edges)
    # queries
    q = random.randint(1, 5)
    queries = []
    for _ in range(q):
        k = random.randint(1, max(1, n-1))
        S = random.sample(range(m), k)
        queries.append(S)
    # build input for program
    lines = []
    lines.append(f"{n} {m}")
    for (u,v,w) in edges:
        lines.append(f"{u} {v} {w}")
    lines.append(str(q))
    for S in queries:
        lines.append(str(len(S)) + " " + " ".join(str(x+1) for x in S))
    input_str = "\n".join(lines) + "\n"

    # run program
    proc = subprocess.run(["./main"], input=input_str.encode(), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    prog_out = proc.stdout.decode().strip().splitlines()
    brute_out = brute_force(n, edges, queries)

    if prog_out != brute_out:
        print("Mismatch found!")
        print("Input:")
        print(input_str)
        print("Program output:", prog_out)
        print("Brute force output:", brute_out)
        exit(1)
print("All random tests passed.")
